    if (n >= 8) break;
    if (+f.size > 10 * 1024 * 1024) continue;
    if (String(f.modifiedTime || f.createdTime || '') < (e.desde || DESDE)) continue; // anterior a la fecha de corte: no se usa
    const esDoc = DOC.includes(f.mimeType), hoja = HOJA[f.mimeType];
    if (!esDoc && !hoja) continue;
    const url = f.mimeType === 'application/vnd.google-apps.spreadsheet'
