// Detecta columnas de fecha, descripción y monto (o cargo/abono) y agrupa las filas por archivo.
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').trim();
const num = (v) => { if (typeof v === 'number') return v; let s = String(v ?? '').trim(); if (!s || s === '-') return 0; const neg = /^\(.*\)$/.test(s) || /^-/.test(s) || /-\s*$/.test(s); s = s.replace(/[^\d.,]/g, ''); if (/,\d{1,2}$/.test(s) && !/\.\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, ''); const n = parseFloat(s) || 0; return neg ? -n : n; };
const fecha = (v) => { if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899, 11, 30) + v * 864e5).toISOString().slice(0, 10); const s = String(v ?? '').trim(); let m; if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return m[0]; if ((m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/))) return `${m[3].length === 2 ? '20' + m[3] : m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`; return ''; };
