  const movimientos = filas.map((r) => ({ fecha: fecha(r[kF]), descripcion: String(r[kD] ?? '').slice(0, 200), monto: kM ? num(r[kM]) : (kA ? Math.abs(num(r[kA])) : 0) - (kC ? Math.abs(num(r[kC])) : 0) }))
    .filter((m) => m.fecha && m.monto && m.fecha >= (src.desde || '2025-01-01')).map((m) => ({ ...m, monto: Math.round(m.monto * 100) / 100 }));
