// Valida el JSON de Claude, decide a qué empresa pertenece por el RUC del receptor y deja todo «por revisar».
const RUCS = { '20615227685': 'BMG', '20602354785': 'MZA', '20616628144': 'MAAS' };
const n = (v) => (v === null || v === undefined || v === '' || isNaN(+v) ? null : Math.round(+v * 100) / 100);
