  if (d) {
    const tipos = ['factura', 'recibo_honorarios', 'boleta', 'nota_credito', 'voucher', 'estado_cuenta', 'otro'];
    d.tipo = tipos.includes(d.tipo) ? d.tipo : 'otro';
    for (const k of ['subtotal', 'igv', 'total', 'retencion']) d[k] = n(d[k]);
    if (d.pago) d.pago.monto = n(d.pago.monto);
    d.movimientos = (Array.isArray(d.movimientos) ? d.movimientos : []).slice(0, 1500).map((m) => ({ fecha: String(m.fecha || '').slice(0, 10), descripcion: String(m.descripcion || '').slice(0, 200), monto: n(m.monto) })).filter((m) => m.fecha && m.monto);
    d.items = (Array.isArray(d.items) ? d.items : []).slice(0, 60);
  }
  const D0 = src.desde || '2025-01-01';
  if (d) d.movimientos = d.movimientos.filter((m) => m.fecha >= D0);
