    ...base, tipo: d?.tipo || 'otro', estado: error ? 'error' : anterior ? 'omitido' : 'por_revisar', nota: anterior ? 'Documento anterior a ' + D0 + ': no se usa (regla de Gerencia).' : undefined, error: error || undefined, empresa_detectada: empresaDetectada, avisos, datos: d || {}, modelo: r.model || null } } };
});

